import {chromium} from 'playwright';
const browser = await chromium.launch({args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 900, height: 500}});
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.addInitScript(() => {
  const liveIntervals = new Set();
  const rafs = new Set();
  const origSI = window.setInterval, origCI = window.clearInterval;
  window.setInterval = (...a) => { const id = origSI(...a); liveIntervals.add(id); return id; };
  window.clearInterval = (id) => { liveIntervals.delete(id); return origCI(id); };
  const origRAF = window.requestAnimationFrame, origCAF = window.cancelAnimationFrame;
  window.requestAnimationFrame = (cb) => { const id = origRAF((t) => { rafs.delete(id); cb(t); }); rafs.add(id); return id; };
  window.cancelAnimationFrame = (id) => { rafs.delete(id); return origCAF(id); };
  const observed = new Set();
  const OrigRO = window.ResizeObserver;
  window.ResizeObserver = class extends OrigRO {
    observe(t, o) { observed.add(t); return super.observe(t, o); }
    unobserve(t) { observed.delete(t); return super.unobserve(t); }
    disconnect() { observed.clear(); return super.disconnect(); }
  };
  window.__probe = { intervals: () => liveIntervals.size, rafs: () => rafs.size, observed: () => observed.size };
});
await page.goto('http://127.0.0.1:5173/probe.html', {waitUntil: 'networkidle'});
await page.waitForSelector('canvas');
await page.waitForTimeout(4500); // несколько тиков фида под StrictMode
const before = await page.evaluate(() => ({ ...Object.fromEntries(Object.entries(window.__probe).map(([k, f]) => [k, f()])), canvases: document.querySelectorAll('canvas').length }));
await page.evaluate(() => window.__hide());
await page.waitForTimeout(300);
const after = await page.evaluate(() => ({ ...Object.fromEntries(Object.entries(window.__probe).map(([k, f]) => [k, f()])), canvases: document.querySelectorAll('canvas').length }));
console.log('mounted (StrictMode, after ticks):', JSON.stringify(before));
console.log('after unmount:', JSON.stringify(after));
console.log('errors:', errors.length ? errors : 'none');
await browser.close();
EOF
